<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Message } from '@arco-design/web-vue'
import PageHeader from '@/components/PageHeader.vue'

interface Envelope<T> { data: T }
interface Organization { id: string; name: string }
interface Project { id: string; organizationId: string; name: string; code: string }
interface Context { organizations: Organization[]; projects: Record<string, Project[]> }
type Platform = 'ANDROID' | 'IOS'
type StepType = 'LAUNCH' | 'TAP' | 'INPUT' | 'ASSERT_VISIBLE' | 'ASSERT_TEXT' | 'WAIT' | 'SCREENSHOT'
interface Device { id: string; name: string; platform: Platform; udid: string; automationName: string; capabilities: Record<string, string>; enabled: boolean; updatedAt: string }
interface App { id: string; name: string; platform: Platform; appIdentifier: string; versionName: string; appFileId?: string; enabled: boolean; updatedAt: string }
interface Element { id: string; name: string; platform: Platform; locatorStrategy: string; locatorValue: string; description: string; updatedAt: string }
interface Step { id: string; type: StepType; name: string; elementId?: string; value?: string; expectedText?: string; timeoutMillis?: number }
interface Scenario { id: string; deviceId: string; applicationId: string; name: string; description: string; failureStrategy: 'STOP' | 'CONTINUE'; variables: Record<string, string>; steps: Step[]; version: number; updatedAt: string }
interface Execution { id: string; taskId: string; scenarioId: string; scenarioName: string; deviceName: string; applicationName: string; platform: Platform; status: string; statusCode?: string; statusMessage?: string; runnerId?: string; requestedAt: string; cancelRequestedAt?: string }
interface Artifact { id: string; artifactType: 'SCREENSHOT'; originalName: string; contentType: string; sizeBytes: number; createdAt: string }
interface Snapshot { devices: Device[]; applications: App[]; elements: Element[]; scenarios: Scenario[]; executions: Execution[] }
interface Report { execution: Execution; summary: { totalSteps: number; passedSteps: number; failedSteps: number; totalDurationMillis: number }; steps: Array<{ id: string; stepSequence: number; stepName: string; stepType: StepType; outcome: string; durationMillis: number; errorMessage?: string }> }

const context = ref<Context | null>(null); const projectId = ref(''); const assets = ref<Snapshot>({ devices: [], applications: [], elements: [], scenarios: [], executions: [] }); const loading = ref(true); const saving = ref(false); const selectedScenarioId = ref(''); const deviceVisible = ref(false); const appVisible = ref(false); const elementVisible = ref(false); const scenarioVisible = ref(false); const executeVisible = ref(false); const reportVisible = ref(false); const report = ref<Report | null>(null); const reportArtifacts = ref<Artifact[]>([]); const executionTarget = ref<Scenario | null>(null)
const deviceForm = reactive({ name: '', platform: 'ANDROID' as Platform, udid: '', automationName: 'UiAutomator2', capabilitiesText: '{}', enabled: true })
const appForm = reactive({ name: '', platform: 'ANDROID' as Platform, appIdentifier: '', versionName: '', appFileId: '', enabled: true })
const elementForm = reactive({ name: '', platform: 'ANDROID' as Platform, locatorStrategy: 'ACCESSIBILITY_ID', locatorValue: '', description: '' })
const scenarioForm = reactive<{ name: string; deviceId: string; applicationId: string; description: string; failureStrategy: 'STOP' | 'CONTINUE'; variablesText: string; steps: Step[] }>({ name: '', deviceId: '', applicationId: '', description: '', failureStrategy: 'STOP', variablesText: '{}', steps: [] })
const executeForm = reactive({ timeoutSeconds: 300 })
const projects = computed(() => context.value?.organizations.flatMap((organization) => context.value?.projects[organization.id] ?? []) ?? [])
const selectedProject = computed(() => projects.value.find((item) => item.id === projectId.value)); const selectedScenario = computed(() => assets.value.scenarios.find((item) => item.id === selectedScenarioId.value) ?? null); const currentScenario = computed<Scenario>(() => selectedScenario.value ?? { id: '', deviceId: '', applicationId: '', name: '', description: '', failureStrategy: 'STOP', variables: {}, steps: [], version: 0, updatedAt: '' })
const stepMeta: Record<StepType, string> = { LAUNCH: '启动应用', TAP: '点击元素', INPUT: '输入内容', ASSERT_VISIBLE: '可见断言', ASSERT_TEXT: '文本断言', WAIT: '等待', SCREENSHOT: '截图' }
const statusText = (value: string) => ({ QUEUED: '排队中', ACCEPTED: '已接收', RUNNING: '运行中', CANCELLING: '取消中', CANCELLED: '已取消', TIMED_OUT: '已超时', SUCCEEDED: '成功', FAILED: '失败', REJECTED: '已拒绝' }[value] ?? value)
const statusColor = (value: string) => ({ QUEUED: 'arcoblue', ACCEPTED: 'cyan', RUNNING: 'orange', CANCELLING: 'orange', CANCELLED: 'gray', TIMED_OUT: 'red', SUCCEEDED: 'green', FAILED: 'red', REJECTED: 'orange' }[value] ?? 'gray')
const date = (value?: string) => value ? new Intl.DateTimeFormat('zh-CN', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : '—'
async function read<T>(url: string, init?: RequestInit): Promise<T> { const response = await fetch(url, { credentials: 'include', ...init }); const body = await response.json().catch(() => ({})) as Envelope<T> & { message?: string }; if (!response.ok) throw new Error(body.message ?? '请求失败，请稍后重试'); return body.data }
async function mutate<T>(url: string, method: 'POST' | 'DELETE', body?: unknown): Promise<T> { const csrf = await read<{ token: string; headerName: string }>('/api/v1/auth/csrf'); return read<T>(url, { method, headers: { 'Content-Type': 'application/json', [csrf.headerName]: csrf.token }, body: body === undefined ? undefined : JSON.stringify(body) }) }
async function loadAssets() { if (!projectId.value) return; assets.value = await read<Snapshot>(`/api/v1/projects/${projectId.value}/mobile-automation`); if (!assets.value.scenarios.some((item) => item.id === selectedScenarioId.value)) selectedScenarioId.value = assets.value.scenarios[0]?.id ?? '' }
async function load() { loading.value = true; try { context.value = await read<Context>('/api/v1/access/context'); projectId.value = projects.value[0]?.id ?? ''; await loadAssets() } catch (error) { Message.error(error instanceof Error ? error.message : '加载移动端自动化资源失败') } finally { loading.value = false } }
async function changeProject() { selectedScenarioId.value = ''; try { await loadAssets() } catch (error) { Message.error(error instanceof Error ? error.message : '切换项目失败') } }
function parse(text: string, label: string) { try { const value = JSON.parse(text || '{}'); if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error(); return value as Record<string, string> } catch { throw new Error(`${label}必须是 JSON 对象`) } }
function resetDevice() { Object.assign(deviceForm, { name: '', platform: 'ANDROID', udid: '', automationName: 'UiAutomator2', capabilitiesText: '{}', enabled: true }) }
function resetApp() { Object.assign(appForm, { name: '', platform: 'ANDROID', appIdentifier: '', versionName: '', appFileId: '', enabled: true }) }
function resetElement() { Object.assign(elementForm, { name: '', platform: 'ANDROID', locatorStrategy: 'ACCESSIBILITY_ID', locatorValue: '', description: '' }) }
function defaultStep(type: StepType = 'LAUNCH'): Step { return { id: `step-${Date.now().toString(36)}-${scenarioForm.steps.length + 1}`, type, name: stepMeta[type], timeoutMillis: type === 'WAIT' ? 1000 : 10000 } }
function resetScenario() { Object.assign(scenarioForm, { name: '', deviceId: assets.value.devices.find((item) => item.enabled)?.id ?? '', applicationId: assets.value.applications.find((item) => item.enabled)?.id ?? '', description: '', failureStrategy: 'STOP', variablesText: '{}', steps: [defaultStep()] }) }
async function saveDevice() { saving.value = true; try { await mutate(`/api/v1/projects/${projectId.value}/mobile-automation/devices`, 'POST', { ...deviceForm, capabilities: parse(deviceForm.capabilitiesText, '设备能力参数') }); deviceVisible.value = false; await loadAssets(); Message.success('设备已保存') } catch (error) { Message.error(error instanceof Error ? error.message : '保存失败') } finally { saving.value = false } }
async function saveApp() { saving.value = true; try { await mutate(`/api/v1/projects/${projectId.value}/mobile-automation/applications`, 'POST', { ...appForm, appFileId: appForm.appFileId || null }); appVisible.value = false; await loadAssets(); Message.success('移动应用已保存') } catch (error) { Message.error(error instanceof Error ? error.message : '保存失败') } finally { saving.value = false } }
async function saveElement() { saving.value = true; try { await mutate(`/api/v1/projects/${projectId.value}/mobile-automation/elements`, 'POST', elementForm); elementVisible.value = false; await loadAssets(); Message.success('元素对象已保存') } catch (error) { Message.error(error instanceof Error ? error.message : '保存失败') } finally { saving.value = false } }
async function saveScenario() { saving.value = true; try { await mutate<Scenario>(`/api/v1/projects/${projectId.value}/mobile-automation/scenarios`, 'POST', { ...scenarioForm, variables: parse(scenarioForm.variablesText, '场景变量') }); scenarioVisible.value = false; await loadAssets(); selectedScenarioId.value = assets.value.scenarios[0]?.id ?? ''; Message.success('移动端场景已保存') } catch (error) { Message.error(error instanceof Error ? error.message : '保存失败') } finally { saving.value = false } }
async function remove(path: string, label: string) { try { await mutate(path, 'DELETE'); await loadAssets(); Message.success(`${label}已删除`) } catch (error) { Message.error(error instanceof Error ? error.message : '删除失败') } }
function openExecution(item: Scenario) { executionTarget.value = item; executeForm.timeoutSeconds = 300; executeVisible.value = true }
async function execute() { if (!executionTarget.value) return; saving.value = true; try { await mutate(`/api/v1/projects/${projectId.value}/mobile-automation/scenarios/${executionTarget.value.id}/executions`, 'POST', executeForm); executeVisible.value = false; await loadAssets(); Message.success('场景已进入隔离 Appium Runner 队列') } catch (error) { Message.error(error instanceof Error ? error.message : '提交执行失败') } finally { saving.value = false } }
async function openReport(item: Execution) { reportVisible.value = true; report.value = null; reportArtifacts.value = []; try { const [value, artifacts] = await Promise.all([read<Report>(`/api/v1/projects/${projectId.value}/mobile-automation/executions/${item.id}/report`), read<Artifact[]>(`/api/v1/projects/${projectId.value}/mobile-automation/executions/${item.id}/artifacts`)]); report.value = value; reportArtifacts.value = artifacts } catch (error) { Message.error(error instanceof Error ? error.message : '加载报告失败') } }
function cancellable(status: string) { return ['QUEUED', 'ACCEPTED', 'RUNNING', 'CANCELLING'].includes(status) }
async function cancelExecution() { if (!report.value) return; saving.value = true; try { await mutate(`/api/v1/projects/${projectId.value}/mobile-automation/executions/${report.value.execution.id}/cancel`, 'POST'); await loadAssets(); await openReport(report.value.execution); Message.success('取消请求已发送至隔离 Appium Runner') } catch (error) { Message.error(error instanceof Error ? error.message : '取消执行失败') } finally { saving.value = false } }
function artifactUrl(artifact: Artifact, mode: 'view' | 'download') { return `/api/v1/projects/${projectId.value}/mobile-automation/executions/${report.value?.execution.id}/artifacts/${artifact.id}/${mode}` }
function elementFor(step: Step) { return assets.value.elements.find((item) => item.id === step.elementId) }
function requiresElement(type: StepType) { return ['TAP', 'INPUT', 'ASSERT_VISIBLE', 'ASSERT_TEXT'].includes(type) }
onMounted(() => { void load() })
</script>

<template>
  <div class="page mobile-automation-page">
    <PageHeader eyebrow="APPIUM RUNNER · ISOLATED DEVICE EXECUTION" title="移动端自动化" description="管理项目设备、应用包、元素对象和声明式移动端场景；设备操作仅在独立 Appium Runner 内发生。" action="新建场景" @action="resetScenario(); scenarioVisible = true" />
    <section class="summary panel"><div><span>当前项目</span><strong>{{ selectedProject?.name ?? '未分配' }}</strong><small>{{ selectedProject?.code ?? '—' }}</small></div><a-select v-model="projectId" :style="{ width: '230px' }" @change="changeProject"><a-option v-for="item in projects" :key="item.id" :value="item.id">{{ item.name }}</a-option></a-select><div><span>设备</span><strong>{{ assets.devices.length }}</strong><small>{{ assets.devices.filter((item) => item.enabled).length }} 个已启用</small></div><div><span>应用</span><strong>{{ assets.applications.length }}</strong><small>包标识与版本快照</small></div><div><span>元素对象</span><strong>{{ assets.elements.length }}</strong><small>跨场景复用</small></div><div><span>移动端场景</span><strong>{{ assets.scenarios.length }}</strong><small>不可变执行清单</small></div></section>
    <a-alert type="info" :show-icon="true" class="safety">Appium Runner 默认禁用执行。需要部署设备农场适配器、限定其网络访问并显式启用后，才会实际访问设备；控制面不执行任何用户脚本或设备命令。</a-alert>
    <section class="assets panel"><a-tabs default-active-key="devices"><a-tab-pane key="devices" title="设备"><div class="toolbar"><span>UDID 仅在项目作用域保存，场景执行时冻结设备快照。</span><a-button type="primary" size="small" @click="resetDevice(); deviceVisible = true">新建设备</a-button></div><a-table :data="assets.devices" :pagination="false" row-key="id" size="small"><template #columns><a-table-column title="名称" data-index="name" /><a-table-column title="平台"><template #cell="{ record }"><a-tag :color="record.platform === 'ANDROID' ? 'green' : 'arcoblue'">{{ record.platform }}</a-tag></template></a-table-column><a-table-column title="UDID" data-index="udid" /><a-table-column title="引擎" data-index="automationName" /><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="record.enabled ? 'green' : 'gray'">{{ record.enabled ? '已启用' : '已停用' }}</a-tag></template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-button size="mini" status="danger" @click="remove(`/api/v1/projects/${projectId}/mobile-automation/devices/${record.id}`, '设备')">删除</a-button></template></a-table-column></template></a-table><a-empty v-if="!loading && !assets.devices.length" description="尚未配置移动设备" /></a-tab-pane>
      <a-tab-pane key="apps" title="应用包"><div class="toolbar"><span>应用包可关联项目文件；首节点先冻结包标识、版本和文件标识。</span><a-button type="primary" size="small" @click="resetApp(); appVisible = true">新建应用</a-button></div><a-table :data="assets.applications" :pagination="false" row-key="id" size="small"><template #columns><a-table-column title="名称" data-index="name" /><a-table-column title="平台" data-index="platform" /><a-table-column title="应用标识" data-index="appIdentifier" /><a-table-column title="版本" data-index="versionName" /><a-table-column title="操作"><template #cell="{ record }"><a-button size="mini" status="danger" @click="remove(`/api/v1/projects/${projectId}/mobile-automation/applications/${record.id}`, '应用')">删除</a-button></template></a-table-column></template></a-table><a-empty v-if="!loading && !assets.applications.length" description="尚未登记移动应用" /></a-tab-pane>
      <a-tab-pane key="elements" title="元素对象"><div class="toolbar"><span>优先使用 accessibility id；XPath 仅用于无稳定标识的兼容场景。</span><a-button type="primary" size="small" @click="resetElement(); elementVisible = true">新建元素</a-button></div><a-table :data="assets.elements" :pagination="false" row-key="id" size="small"><template #columns><a-table-column title="名称" data-index="name" /><a-table-column title="平台" data-index="platform" /><a-table-column title="策略" data-index="locatorStrategy" /><a-table-column title="定位值"><template #cell="{ record }"><code>{{ record.locatorValue }}</code></template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-button size="mini" status="danger" @click="remove(`/api/v1/projects/${projectId}/mobile-automation/elements/${record.id}`, '元素')">删除</a-button></template></a-table-column></template></a-table><a-empty v-if="!loading && !assets.elements.length" description="尚未配置元素对象" /></a-tab-pane></a-tabs></section>
    <section class="workspace"><aside class="panel scenarios"><header><div><span class="eyebrow">MOBILE FLOWS</span><h3>自动化场景</h3></div><a-button type="primary" size="small" @click="resetScenario(); scenarioVisible = true">新建</a-button></header><button v-for="item in assets.scenarios" :key="item.id" class="scenario" :class="{ selected: selectedScenarioId === item.id }" @click="selectedScenarioId = item.id"><span><strong>{{ item.name }}</strong><small>{{ assets.devices.find((device) => device.id === item.deviceId)?.name ?? '设备已删除' }}</small></span><a-tag size="small">{{ item.steps.length }}</a-tag></button><a-empty v-if="!loading && !assets.scenarios.length" description="尚无场景" /></aside>
      <main v-if="selectedScenarioId" class="scenario-main"><section class="panel scenario-header"><div><span class="eyebrow">IMMUTABLE DEVICE MANIFEST</span><h2>{{ currentScenario.name }}</h2><p>{{ currentScenario.description || '暂无场景说明' }}</p></div><a-space><a-button type="primary" @click="openExecution(currentScenario)">执行场景</a-button><a-button status="danger" @click="remove(`/api/v1/projects/${projectId}/mobile-automation/scenarios/${currentScenario.id}`, '场景')">删除</a-button></a-space></section><section class="overview panel"><div><span>目标设备</span><strong>{{ assets.devices.find((item) => item.id === currentScenario.deviceId)?.name ?? '已删除' }}</strong></div><div><span>应用</span><strong>{{ assets.applications.find((item) => item.id === currentScenario.applicationId)?.name ?? '已删除' }}</strong></div><div><span>失败策略</span><strong>{{ currentScenario.failureStrategy === 'CONTINUE' ? '失败后继续' : '首次失败停止' }}</strong></div><div><span>步骤</span><strong>{{ currentScenario.steps.length }}</strong></div></section><section class="panel steps"><header><div><span class="eyebrow">DECLARATIVE APPIUM FLOW</span><h3>移动端步骤</h3></div><span>无脚本 · 受限设备边界</span></header><ol><li v-for="(step, index) in currentScenario.steps" :key="step.id"><b>{{ index + 1 }}</b><article><a-tag color="arcoblue">{{ stepMeta[step.type] }}</a-tag><strong>{{ step.name }}</strong><small>{{ step.timeoutMillis }}ms</small><code v-if="elementFor(step)">{{ elementFor(step)?.locatorStrategy }} · {{ elementFor(step)?.locatorValue }}</code><p v-if="step.value">输入：{{ step.value }}</p><p v-if="step.expectedText">期望：{{ step.expectedText }}</p></article></li></ol></section><section class="panel history"><header><h3>执行记录</h3><a-button size="small" @click="loadAssets">刷新</a-button></header><a-table :data="assets.executions.filter((item) => item.scenarioId === currentScenario.id)" :pagination="false" row-key="id" size="small"><template #columns><a-table-column title="任务"><template #cell="{ record }"><strong>{{ record.taskId }}</strong><small>{{ record.deviceName }} · {{ record.applicationName }}</small></template></a-table-column><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="statusColor(record.status)">{{ statusText(record.status) }}</a-tag><small>{{ record.statusCode }}</small></template></a-table-column><a-table-column title="提交时间"><template #cell="{ record }">{{ date(record.requestedAt) }}</template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-button size="mini" @click="openReport(record)">报告</a-button></template></a-table-column></template></a-table><a-empty v-if="!assets.executions.some((item) => item.scenarioId === currentScenario.id)" description="当前场景暂无执行记录" /></section></main>
      <main v-else class="panel empty"><a-empty description="创建一个移动端场景开始编排"><template #extra><a-button type="primary" @click="resetScenario(); scenarioVisible = true">创建场景</a-button></template></a-empty></main></section>
    <a-modal v-model:visible="deviceVisible" title="新建设备" :ok-loading="saving" @ok="saveDevice"><a-form :model="deviceForm" layout="vertical"><div class="two"><a-form-item label="设备名称" required><a-input v-model="deviceForm.name" placeholder="例如：Pixel 8 · Android 15" /></a-form-item><a-form-item label="平台"><a-select v-model="deviceForm.platform"><a-option value="ANDROID">Android</a-option><a-option value="IOS">iOS</a-option></a-select></a-form-item></div><div class="two"><a-form-item label="UDID" required><a-input v-model="deviceForm.udid" placeholder="设备序列号或云真机 ID" /></a-form-item><a-form-item label="Appium 引擎" required><a-input v-model="deviceForm.automationName" placeholder="UiAutomator2 / XCUITest" /></a-form-item></div><a-form-item label="能力参数（JSON）"><a-textarea v-model="deviceForm.capabilitiesText" :auto-size="{ minRows: 3, maxRows: 6 }" placeholder="{ &quot;appium:platformVersion&quot;: &quot;15&quot; }" /></a-form-item><a-form-item label="启用设备"><a-switch v-model="deviceForm.enabled" checked-text="启用" unchecked-text="停用" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="appVisible" title="新建移动应用" :ok-loading="saving" @ok="saveApp"><a-form :model="appForm" layout="vertical"><div class="two"><a-form-item label="应用名称" required><a-input v-model="appForm.name" placeholder="例如：交易客户端 Android" /></a-form-item><a-form-item label="平台"><a-select v-model="appForm.platform"><a-option value="ANDROID">Android</a-option><a-option value="IOS">iOS</a-option></a-select></a-form-item></div><div class="two"><a-form-item label="应用包标识" required><a-input v-model="appForm.appIdentifier" placeholder="com.example.trade" /></a-form-item><a-form-item label="版本"><a-input v-model="appForm.versionName" placeholder="3.2.0" /></a-form-item></div><a-form-item label="项目文件标识（可选）"><a-input v-model="appForm.appFileId" placeholder="关联已上传的 APK / IPA 文件 ID" /></a-form-item><a-form-item label="启用应用"><a-switch v-model="appForm.enabled" checked-text="启用" unchecked-text="停用" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="elementVisible" title="新建元素对象" :ok-loading="saving" @ok="saveElement"><a-form :model="elementForm" layout="vertical"><div class="two"><a-form-item label="元素名称" required><a-input v-model="elementForm.name" placeholder="例如：登录按钮" /></a-form-item><a-form-item label="平台"><a-select v-model="elementForm.platform"><a-option value="ANDROID">Android</a-option><a-option value="IOS">iOS</a-option></a-select></a-form-item></div><div class="two"><a-form-item label="定位策略"><a-select v-model="elementForm.locatorStrategy"><a-option value="ACCESSIBILITY_ID">Accessibility ID</a-option><a-option value="ID">ID</a-option><a-option value="XPATH">XPath</a-option><a-option value="ANDROID_UIAUTOMATOR">Android UiAutomator</a-option><a-option value="IOS_PREDICATE">iOS Predicate</a-option></a-select></a-form-item><a-form-item label="定位值" required><a-input v-model="elementForm.locatorValue" /></a-form-item></div><a-form-item label="说明"><a-textarea v-model="elementForm.description" :auto-size="{ minRows: 2, maxRows: 4 }" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="scenarioVisible" title="新建移动端场景" width="900px" :ok-loading="saving" @ok="saveScenario"><a-form :model="scenarioForm" layout="vertical"><div class="two"><a-form-item label="场景名称" required><a-input v-model="scenarioForm.name" placeholder="例如：用户登录成功" /></a-form-item><a-form-item label="设备" required><a-select v-model="scenarioForm.deviceId" placeholder="选择已启用设备"><a-option v-for="item in assets.devices.filter((device) => device.enabled)" :key="item.id" :value="item.id">{{ item.name }} · {{ item.platform }}</a-option></a-select></a-form-item></div><div class="two"><a-form-item label="应用" required><a-select v-model="scenarioForm.applicationId" placeholder="选择应用"><a-option v-for="item in assets.applications.filter((app) => app.enabled)" :key="item.id" :value="item.id">{{ item.name }} · {{ item.platform }}</a-option></a-select></a-form-item><a-form-item label="失败策略"><a-radio-group v-model="scenarioForm.failureStrategy"><a-radio value="STOP">首次失败停止</a-radio><a-radio value="CONTINUE">失败后继续</a-radio></a-radio-group></a-form-item></div><a-form-item label="场景说明"><a-textarea v-model="scenarioForm.description" :auto-size="{ minRows: 2, maxRows: 3 }" /></a-form-item><a-form-item label="变量（JSON 对象）"><a-textarea v-model="scenarioForm.variablesText" :auto-size="{ minRows: 2, maxRows: 4 }" placeholder="{ &quot;phone&quot;: &quot;13800000000&quot; }" /></a-form-item><div class="form-heading"><strong>声明式步骤</strong><a-select :model-value="'LAUNCH'" :style="{ width: '160px' }" @change="(value) => scenarioForm.steps.push(defaultStep(value as StepType))"><a-option v-for="type in Object.keys(stepMeta)" :key="type" :value="type">添加 {{ stepMeta[type as StepType] }}</a-option></a-select></div><article v-for="(step, index) in scenarioForm.steps" :key="step.id" class="step-form"><header><strong>步骤 {{ index + 1 }}</strong><a-space><a-select v-model="step.type" :style="{ width: '140px' }"><a-option v-for="type in Object.keys(stepMeta)" :key="type" :value="type">{{ stepMeta[type as StepType] }}</a-option></a-select><a-button type="text" status="danger" :disabled="scenarioForm.steps.length === 1" @click="scenarioForm.steps.splice(index, 1)">删除</a-button></a-space></header><div class="two"><a-form-item label="步骤名称"><a-input v-model="step.name" /></a-form-item><a-form-item v-if="requiresElement(step.type)" label="元素对象"><a-select v-model="step.elementId" placeholder="选择元素"><a-option v-for="item in assets.elements" :key="item.id" :value="item.id">{{ item.name }} · {{ item.locatorStrategy }}</a-option></a-select></a-form-item><a-form-item v-else label="步骤超时（毫秒）"><a-input-number v-model="step.timeoutMillis" :min="1" :max="60000" /></a-form-item></div><a-form-item v-if="step.type === 'INPUT'" label="输入内容"><a-input v-model="step.value" placeholder="可使用 {{phone}}" /></a-form-item><a-form-item v-if="step.type === 'ASSERT_TEXT'" label="期望文本"><a-input v-model="step.expectedText" /></a-form-item><a-form-item v-if="step.type !== 'WAIT' && step.type !== 'SCREENSHOT'" label="步骤超时（毫秒）"><a-input-number v-model="step.timeoutMillis" :min="1" :max="60000" /></a-form-item></article></a-form></a-modal>
    <a-modal v-model:visible="executeVisible" title="执行移动端场景" :ok-loading="saving" @ok="execute"><a-form :model="executeForm" layout="vertical"><a-alert type="info" :show-icon="true">执行清单将在排队时冻结；设备命令不会进入控制面，仅在隔离 Appium Runner 中执行。</a-alert><a-form-item label="执行超时（秒）"><a-input-number v-model="executeForm.timeoutSeconds" :min="10" :max="3600" /></a-form-item></a-form></a-modal>
    <a-drawer v-model:visible="reportVisible" width="640px" :footer="false"><template #title>移动端自动化报告</template><a-spin :loading="!report"><template v-if="report"><section class="report-title"><div><strong>{{ report.execution.scenarioName }}</strong><small>{{ report.execution.taskId }}</small></div><a-space><a-button v-if="cancellable(report.execution.status)" size="small" status="warning" :loading="saving" @click="cancelExecution">取消执行</a-button><a-tag :color="statusColor(report.execution.status)">{{ statusText(report.execution.status) }}</a-tag></a-space></section><p v-if="report.execution.statusMessage" class="status-message">{{ report.execution.statusMessage }}</p><div class="report-summary"><div><span>步骤数</span><strong>{{ report.summary.totalSteps }}</strong></div><div><span>通过</span><strong>{{ report.summary.passedSteps }}</strong></div><div><span>失败</span><strong>{{ report.summary.failedSteps }}</strong></div><div><span>累计耗时</span><strong>{{ report.summary.totalDurationMillis }}ms</strong></div></div><section class="artifacts"><header><strong>执行截图</strong><small>{{ reportArtifacts.length }} 个</small></header><div v-if="reportArtifacts.length" class="artifact-grid"><article v-for="artifact in reportArtifacts" :key="artifact.id"><img :src="artifactUrl(artifact, 'view')" :alt="artifact.originalName" /><footer><span>{{ (artifact.sizeBytes / 1024).toFixed(1) }} KB</span><a :href="artifactUrl(artifact, 'download')">下载</a></footer></article></div><a-empty v-else description="尚无截图工件" /></section><a-timeline><a-timeline-item v-for="step in report.steps" :key="step.id" :dot-color="step.outcome === 'PASSED' ? 'green' : step.outcome === 'SKIPPED' ? 'gray' : 'red'" :label="`#${step.stepSequence} · ${step.durationMillis}ms`"><strong>{{ step.stepName }}</strong><a-tag size="small" :color="step.outcome === 'PASSED' ? 'green' : step.outcome === 'SKIPPED' ? 'gray' : 'red'">{{ step.outcome }}</a-tag><p v-if="step.errorMessage">{{ step.errorMessage }}</p></a-timeline-item></a-timeline><a-empty v-if="!report.steps.length" description="等待 Appium Runner 回传步骤结果" /></template></a-spin></a-drawer>
  </div>
</template>

